// Typed client for the red-team API. Types come from schema.d.ts, generated by:
//   python scripts/export_openapi.py && npm run api:types
import { api, post } from '../api';
import type { components } from './schema';

export type S = components['schemas'];
export type Catalog = S['Catalog'];
export type ModelEntry = S['ModelEntry'];
export type EnvironmentEntry = S['EnvironmentEntry'];
export type PluginEntry = S['PluginEntry'];
export type ExperimentConfig = S['ExperimentConfig'];
export type PluginUse = S['PluginUse'];
export type ValidationResult = S['ValidationResult'];
export type StepIssue = S['StepIssue'];
export type PluginCheck = S['PluginCheck'];
export type Arm = S['Arm'];
export type Experiment = S['Experiment'];
export type ExperimentRun = S['ExperimentRun'];
export type EpisodeRow = S['EpisodeRow'];
export type EpisodePage = S['EpisodePage'];
export type EpisodeDetail = S['EpisodeDetail'];
export type Trace = S['Trace'];
export type TraceStep = S['TraceStep'];
export type Report = S['Report'];
export type ArmStats = S['ArmStats'];
export type Delta = S['Delta'];
export type Matrix = S['Matrix'];
export type Stage = PluginEntry['stage'];
export type Role = PluginEntry['role'];

export interface EpisodeQuery {
  arm?: string; environment?: string; success?: boolean; end_reason?: string; hazard?: string; cursor?: string; limit?: number;
}

const enc = encodeURIComponent;
const query = (params: object) => {
  const entries = Object.entries(params).filter(([, v]) => v !== undefined && v !== '');
  return entries.length ? '?' + new URLSearchParams(entries.map(([k, v]) => [k, String(v)])).toString() : '';
};
const put = <T,>(path: string, value: unknown) => api<T>(path, { method: 'PUT', body: JSON.stringify(value) });
const ex = (id: string) => `/experiments/${enc(id)}`;
const epPath = (id: string, episode: string) => `${ex(id)}/episodes/${enc(episode)}`;

export const redteam = {
  catalog: () => api<Catalog>('/catalog'),
  validate: (config: ExperimentConfig) => post<ValidationResult>('/experiments/validate', config),
  getDraft: (id: string) => api<S['Draft']>(`/experiments/drafts/${enc(id)}`),
  putDraft: (id: string, config: ExperimentConfig) => put<S['Draft']>(`/experiments/drafts/${enc(id)}`, config),
  submit: (config: ExperimentConfig) => post<Experiment>('/experiments', config),
  list: () => api<S['ExperimentPage']>('/experiments'),
  get: (id: string) => api<Experiment>(ex(id)),
  cancel: (id: string) => post<Experiment>(`${ex(id)}/cancel`),
  logs: (id: string, runId: string, offset = 0) => api<S['LogChunk']>(`${ex(id)}/logs${query({ run_id: runId, offset })}`),
  eventsUrl: (id: string) => `/api/v1${ex(id)}/events`,
  episodes: (id: string, q: EpisodeQuery = {}) => api<EpisodePage>(`${ex(id)}/episodes${query(q)}`),
  episode: (id: string, episode: string) => api<EpisodeDetail>(epPath(id, episode)),
  trace: (id: string, episode: string, start?: number, end?: number) => api<Trace>(`${epPath(id, episode)}/trace${query({ start, end })}`),
  frameUrl: (id: string, episode: string, camera: string, index: number) => `/api/v1${epPath(id, episode)}/frames/${enc(camera)}/${index}.png`,
  report: (id: string) => api<Report>(`${ex(id)}/report`),
  matrix: (id: string) => api<Matrix>(`${ex(id)}/matrix`),
};
